package run.ikaros.sharing; import java.time.Instant; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; import run.ikaros.common.ConflictException; import run.ikaros.common.NotFoundException; @Service public class PersistentRoomService implements RoomService{private final RoomRepository rooms;private final RoomMembershipRepository members;public PersistentRoomService(RoomRepository r,RoomMembershipRepository m){rooms=r;members=m;}public Mono<RoomView> create(UUID a,CreateRoomRequest r){if(r.expiresAt()!=null&&!r.expiresAt().isAfter(Instant.now()))return Mono.error(new IllegalArgumentException("Room 过期时间必须在未来"));Instant n=Instant.now();RoomEntity x=new RoomEntity(null,a,r.kind(),r.targetType(),r.targetId(),r.visibility()==null?"PRIVATE":r.visibility(),RoomStatus.ACTIVE,0,0,r.expiresAt(),n,n,null);return rooms.save(x).flatMap(saved->members.save(new RoomMembershipEntity(null,saved.id(),a,RoomRole.OWNER,n,null,n,null)).thenReturn(view(saved)));}public Flux<RoomView> list(UUID a){return rooms.findAllByOwnerIdOrderByCreatedAtDesc(a).map(this::view);}public Mono<RoomView> lock(UUID a,UUID id){return owner(a,id).flatMap(x->change(x,RoomStatus.LOCKED));}public Mono<RoomView> unlock(UUID a,UUID id){return owner(a,id).flatMap(x->change(x,RoomStatus.ACTIVE));}public Mono<RoomView> end(UUID a,UUID id){return owner(a,id).flatMap(x->change(x,RoomStatus.ENDED));}public Mono<RoomMembershipView> join(UUID a,UUID id){return rooms.findById(id).switchIfEmpty(Mono.error(new NotFoundException("Room 不存在"))).flatMap(r->{if(r.status()!=RoomStatus.ACTIVE)return Mono.error(new ConflictException("Room 当前不可加入"));return members.findByRoomIdAndPrincipalId(id,a).flatMap(m->m.leftAt()==null?Mono.just(m):members.save(new RoomMembershipEntity(m.id(),m.roomId(),m.principalId(),RoomRole.MEMBER,m.joinedAt(),null,Instant.now(),m.version()))).switchIfEmpty(members.save(new RoomMembershipEntity(null,id,a,RoomRole.MEMBER,Instant.now(),null,Instant.now(),null))).map(this::memberView);});}public Mono<RoomMembershipView> leave(UUID a,UUID id){return membership(id,a).flatMap(m->{if(m.role()==RoomRole.OWNER)return Mono.error(new ConflictException("Owner 必须先转移所有权或结束 Room"));return members.save(new RoomMembershipEntity(m.id(),m.roomId(),m.principalId(),m.role(),m.joinedAt(),Instant.now(),Instant.now(),m.version()));}).map(this::memberView);}public Flux<RoomMembershipView> members(UUID a,UUID id){return access(a,id).thenMany(members.findAllByRoomIdAndLeftAtIsNull(id).map(this::memberView));}public Mono<RoomMembershipView> changeRole(UUID a,UUID id,UUID p,RoomRole role){return owner(a,id).then(membership(id,p)).flatMap(m->members.save(new RoomMembershipEntity(m.id(),m.roomId(),m.principalId(),role==RoomRole.OWNER?RoomRole.MEMBER:role,m.joinedAt(),m.leftAt(),Instant.now(),m.version()))).map(this::memberView);}public Mono<RoomMembershipView> transferOwnership(UUID a,UUID id,UUID p){return owner(a,id).flatMap(room->membership(id,p).flatMap(next->members.findByRoomIdAndPrincipalId(id,a).flatMap(old->members.save(new RoomMembershipEntity(old.id(),old.roomId(),old.principalId(),RoomRole.MEMBER,old.joinedAt(),old.leftAt(),Instant.now(),old.version()))).then(members.save(new RoomMembershipEntity(next.id(),next.roomId(),next.principalId(),RoomRole.OWNER,next.joinedAt(),next.leftAt(),Instant.now(),next.version()))).flatMap(saved->rooms.save(new RoomEntity(room.id(),p,room.kind(),room.targetType(),room.targetId(),room.visibility(),room.status(),room.stateVersion()+1,room.sequence(),room.expiresAt(),room.createdAt(),Instant.now(),room.version())).thenReturn(saved)))).map(this::memberView);}public Mono<RoomMembershipView> remove(UUID a,UUID id,UUID p){return owner(a,id).then(membership(id,p)).flatMap(m->{if(m.role()==RoomRole.OWNER)return Mono.error(new ConflictException("不能移除 Owner"));return members.save(new RoomMembershipEntity(m.id(),m.roomId(),m.principalId(),m.role(),m.joinedAt(),Instant.now(),Instant.now(),m.version()));}).map(this::memberView);}private Mono<RoomEntity> owner(UUID a,UUID id){return rooms.findById(id).filter(r->r.ownerId().equals(a)).switchIfEmpty(Mono.error(new NotFoundException("Room 不存在或无权操作")));}private Mono<Void> access(UUID a,UUID id){return members.findByRoomIdAndPrincipalId(id,a).filter(m->m.leftAt()==null).switchIfEmpty(Mono.error(new NotFoundException("Room 不存在或无权访问"))).then();}private Mono<RoomMembershipEntity> membership(UUID id,UUID p){return members.findByRoomIdAndPrincipalId(id,p).filter(m->m.leftAt()==null).switchIfEmpty(Mono.error(new NotFoundException("Room 成员不存在")));}private Mono<RoomView> change(RoomEntity r,RoomStatus s){return rooms.save(new RoomEntity(r.id(),r.ownerId(),r.kind(),r.targetType(),r.targetId(),r.visibility(),s,r.stateVersion()+1,r.sequence(),r.expiresAt(),r.createdAt(),Instant.now(),r.version())).map(this::view);}private RoomView view(RoomEntity r){return new RoomView(r.id(),r.ownerId(),r.kind(),r.targetType(),r.targetId(),r.visibility(),r.status(),r.stateVersion(),r.sequence(),r.expiresAt(),r.createdAt());}private RoomMembershipView memberView(RoomMembershipEntity m){return new RoomMembershipView(m.id(),m.roomId(),m.principalId(),m.role(),m.joinedAt(),m.leftAt());}}
